# refusals.py RUN_DIR: per agent, tool results marked as errors, with the tool and the first words of the result
import glob, json, os, sys, collections, re
d=sys.argv[1]
for meta in sorted(glob.glob(os.path.join(d,'agent-*.meta.json'))):
    lab=json.load(open(meta))['description']; f=meta.replace('.meta.json','.jsonl')
    names={}; out=[]
    for line in open(f,errors='replace'):
        try: r=json.loads(line)
        except: continue
        m=r.get('message')
        if not isinstance(m,dict): continue
        for x in m.get('content') or []:
            if not isinstance(x,dict): continue
            if x.get('type')=='tool_use': names[x['id']]=x.get('name')
            if x.get('type')=='tool_result' and x.get('is_error'):
                c=x.get('content'); s=c if isinstance(c,str) else ' '.join(y.get('text','') for y in c if isinstance(y,dict))
                s=' '.join(s.split())
                if s.startswith('Exit code'): continue
                out.append(names.get(x.get('tool_use_id'),'?')+': '+s[:110])
    print(f"== {lab} ({len(out)})")
    for k,v in collections.Counter(out).most_common(): print('   ',v,'x',k)
